INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2020, 'Economia', NULL, 'Q1 Item 1 (TPS 2020): Com base nos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Em textos literários, por vezes infringem-se as regras da gramática normativa. No mencionado texto, um exemplo de não observância das regras gramaticais pode ser encontrado na linha 13, no uso da vírgula após “Mas”, e outro exemplo pode ser encontrado na linha 32, na ausência de vírgulas que isolem a conjunção “pois”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q1 Item 2 (TPS 2020): Com base nos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | A partícula “se” em “Está-se aqui, sozinho, sentado à mesa” (linha 15) funciona como índice de indeterminação do sujeito. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 2/15 3 O trecho “Ou, quem sabe? — apenas permanecer numa casa, caixa, onde no quarto durmam crianças, no fogão haja um resto de comida e, na cama, esperando, certa mulherzinha.” (linhas de 21 a 24) poderia ser reescrito, mantendo-se a correção gramatical e os sentidos do texto, da seguinte forma: Ou, quem sabe, apenas permanecer em uma casa-caixa, cujos quartos durmam crianças, em cujo fogão haja um resto de comida e em cuja cama haja uma certa mulherzinha esperando.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q1 Item 3 (TPS 2020): Com base nos aspectos linguísticos e semânticos do texto, julgue (C ou E) os itens a seguir. | Na linha 34, o pronome “o” pode ter como referente tanto o nome “homem” (linha 31) quanto o sintagma “o itinerário” (linha 32); em ambos os casos, a coerência do texto é preservada.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q2 Item 1 (TPS 2020): Considerando as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | Como é usual em textos literários, no texto apresentado, observa-se o emprego recorrente de figuras de linguagem, tais como a prosopopeia, presente em “o papel aceita tudo” (linha 2) e “tipos negros mancham agora uma página branca” (linhas 12 e 13).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q2 Item 2 (TPS 2020): Considerando as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | Para o autor do texto, uma página em branco corresponde a “um universo cheio de vidas escolhíveis” (linhas 17 e 18).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q2 Item 3 (TPS 2020): Considerando as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | O autor implicitamente apresenta uma crítica a dois modos de vida distintos: o de quem se envolve com a criminalidade – em que se faz “o percurso das ruas, artérias, os bares, as favelas, a prostituição, os rituais, os crimes” (linhas 20 e 21) – e o de quem se contenta com a mesmice e a previsibilidade – em que se permanece “numa casa, caixa, onde no quarto durmam crianças, no fogão haja um resto de comida e, na cama, esperando, certa mulherzinha” (linhas de 22 a 24).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q2 Item 4 (TPS 2020): Considerando as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | Nos dois últimos parágrafos do texto (linhas de 30 a 37), o autor sugere que se deve deixar-se levar pelas escolhas que a vida faz, visto que, embora não se perceba, cada homem já nasce com o próprio destino traçado. Área Livre Texto 2 para responder às questões 3 e 4. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 55 58 61 62 “Precisa-se de um professor de língua javanesa. Cartas etc.” Ora, disse cá comigo, está ali uma colocação que não terá muitos concorrentes; se eu capiscasse quatro palavras, ia apresentar-me. Saí do café e andei pelas ruas, sempre a imaginar-me professor de javanês, ganhando dinheiro, andando de bonde e sem encontros desagradáveis com os “cadáveres”. Insensivelmente dirigi-me à Biblioteca Nacional. Não sabia bem que livro iria pedir; mas, entrei, entreguei o chap', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q3 Item 1 (TPS 2020): Tendo em vista as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | De acordo com o texto, o narrador-personagem passava por dificuldades financeiras e, no intuito de conseguir um emprego, tornou-se professor de língua javanesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q3 Item 2 (TPS 2020): Tendo em vista as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | Entre as características do narrador-personagem, destacam-se a sagacidade e a predisposição para a aprendizagem de línguas estrangeiras.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q3 Item 3 (TPS 2020): Tendo em vista as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | No trecho “Convenci-me... cômodos:” (linhas de 28 a 30), fica clara a intenção do narrador-personagem de provocar um encontro com o encarregado dos aluguéis dos cômodos, ao sair de casa cedo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q3 Item 4 (TPS 2020): Tendo em vista as ideias e os sentidos do texto, julgue (C ou E) os itens a seguir. | Ao mencionar o Timor (linha 38), o narrador-personagem diz atacar o patriotismo de seu interlocutor (linha 37), que tem nacionalidade portuguesa, em razão de o Timor já ter sido uma colônia de Portugal e de ser uma localidade na qual se fala a língua portuguesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q4 Item 1 (TPS 2020): Com base nos aspectos gramaticais e semânticos do texto, julgue (C ou E) os itens a seguir. | No texto, a expressão “a língua javanesa” (linha 11) é retomada de diversas maneiras, de modo a evitar sua repetição. Entre essas formas, é correto citar: “a tal língua malaia” (linhas 16 e 17), “o meu ‘a-b-c’ malaio” (linha 26), “a língua mais fácil do mundo” (linhas 28 e 29), “o javanês” (linha 45), “idioma oceânico” (linha 47), “o alfabeto javanês” (linha 51) e “língua malaia” (linha 52).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q4 Item 2 (TPS 2020): Com base nos aspectos gramaticais e semânticos do texto, julgue (C ou E) os itens a seguir. | Embora as relações entre as orações e os termos das orações sejam alteradas, a sentença “Na minha cabeça... escrevê-los.” (linhas de 20 a 23) poderia ser reescrita, mantendo-se a correção e a coerência do texto, da seguinte forma: Na minha cabeça dançavam hieróglifos, de quando em quando, e eu consultava as minhas notas. Entrava nos jardins e, como desejava guardá-los bem na memória e habituar a mão a escrevê-los, escrevia-os na areia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q4 Item 3 (TPS 2020): Com base nos aspectos gramaticais e semânticos do texto, julgue (C ou E) os itens a seguir. | A supressão da preposição “de” (linha 28) manteria a correção gramatical e o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q4 Item 4 (TPS 2020): Com base nos aspectos gramaticais e semânticos do texto, julgue (C ou E) os itens a seguir. | O termo “entrementes” (linha 57) poderia ser substituído no texto, sem prejuízo para sua correção e sem alteração de seu sentido original, por entretanto. Área Livre Texto 3 para responder às questões de 5 a 7. 1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 52 55 57 É a história da emancipação da escravatura entre nós. Outrora a escravidão pareceria fadada à perpetuidade neste País. Falar em extingui-la seria uma blasfêmia. Fizeram-na esposar a lavoura, cuidando uni-las para sempre. A nação tinha edificado a sua fortuna sobre um crime, consagrando-o nos seus códigos como uma necessidade social. Hoje o princípio emancipador, difundido pela civilização, lavrou por toda a parte. Na Europa e na América desapareceu a escravidão. Só nós alimentamos no seio esta ignomínia. A pressão formidável d', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q5 Item 1 (TPS 2020): Considerando as ideias contidas no texto, julgue (C ou E) os itens a seguir. | Ainda que encerre críticas à história da emancipação da escravatura no País, o texto reconhece a importância da herança deixada por esse momento histórico à nação, como aquela que se observa, por exemplo, no manejo da lavoura, mencionada no segundo parágrafo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q5 Item 2 (TPS 2020): Considerando as ideias contidas no texto, julgue (C ou E) os itens a seguir. | O termo “fala”, na expressão “fala do trono de 1869” (linha 15), faz referência, de forma crítica, ao “silêncio” (linha 22) e à “abstenção” (linha 23) do governante, mencionados nas linhas seguintes do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q5 Item 3 (TPS 2020): Considerando as ideias contidas no texto, julgue (C ou E) os itens a seguir. | A despeito dos fatos relatados no texto, observa-se algum otimismo com relação ao futuro do País no que diz respeito à emancipação da escravatura.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q5 Item 4 (TPS 2020): Considerando as ideias contidas no texto, julgue (C ou E) os itens a seguir. | No 13o parágrafo do texto – “Não protesteis! (...) do trono?” (linhas de 38 a 45) –, o autor do texto evidencia o caráter impermanente da emancipação, que ora é tratada como “tão urgente” (linha 39) e como “necessidade capital do País” (linha 41), ora é considerada como “tão secundária, tão indiferente, tão remota” (linhas 43 e 44).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q6 Item 1 (TPS 2020): Com base nos aspectos semânticos e gramaticais do texto, julgue (C ou E) os itens a seguir. | A palavra “ignomínia” (linha 10) foi empregada no texto com o mesmo sentido de opróbrio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q6 Item 2 (TPS 2020): Com base nos aspectos semânticos e gramaticais do texto, julgue (C ou E) os itens a seguir. | A substituição de “neste” (linha 24) por nesse promoveria incorreção ao texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q6 Item 3 (TPS 2020): Com base nos aspectos semânticos e gramaticais do texto, julgue (C ou E) os itens a seguir. | Segundo se depreende do 12o parágrafo do texto (linhas de 29 a 37), o Partido Conservador preteriu “o interesse imorredouro da verdade” (linhas 34 e 35), “as necessidades imperiosas do futuro” (linhas 35 e 36) e “os direitos inalienáveis de uma raça escravizada” (linha 37).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q6 Item 4 (TPS 2020): Com base nos aspectos semânticos e gramaticais do texto, julgue (C ou E) os itens a seguir. | No texto, a locução “desde que” (linha 48) introduz uma condição.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q7 Item 1 (TPS 2020): Tendo em vista a estrutura gramatical do texto, julgue (C ou E) os itens a seguir. | O sujeito segue o verbo nas seguintes orações do texto: “desapareceu a escravidão” (linha 9), “No meio de tudo isto o que fez o governo?” (linha 13) e “Felizmente, porém, há um preceito e um fato de observação” (linhas 46 e 47).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q7 Item 2 (TPS 2020): Tendo em vista a estrutura gramatical do texto, julgue (C ou E) os itens a seguir. | A oração iniciada por “que” (linha 39) introduz uma explicação acerca da oração que inicia o período, sendo classificada como adjetiva explicativa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q7 Item 3 (TPS 2020): Tendo em vista a estrutura gramatical do texto, julgue (C ou E) os itens a seguir. | A forma verbal “há” (linha 46) poderia ser substituída, no texto, tanto por existe quanto por existem, sem que isso acarretasse alteração de sentido ao texto, nem incorreção gramatical.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q7 Item 4 (TPS 2020): Tendo em vista a estrutura gramatical do texto, julgue (C ou E) os itens a seguir. | Com manutenção das ideias e da correção gramatical, o último período do texto poderia ser redigido da seguinte forma: A servidão que temos vivido até hoje, assim como a completa ausência de animação política do País, nos têm habituado a desdenhar desses fatos que, sob a modéstia de suas feições, ocultam graves sistemas de regeneração pública.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q8 Item 1 (TPS 2020): 1 4 7 10 13 16 19 22 25 28 30 5.11. As Partes reconhecem que, ao exercer responsabilidades de Contratação para a outra Parte ou ambas as Partes, em conformidade com um PA*, poderá ser necessário que a Parte Contratante incorra em obrigações contratuais ou outras em benefício da outra Parte ou de ambas as Partes, antes de receber os recursos da outra Parte. No caso em que a Parte Contratante incorra em tais obrigações contratuais ou outras obrigações, a outra Parte deverá pagar a sua parte equita | O art. 5.11 do Acordo RDT\&E estipula que uma Parte poderá beneficiar-se de obrigações contratuais incorridas pela outra Parte somente após o pagamento de sua parte equitativa do Contrato ou outra obrigação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q8 Item 2 (TPS 2020): 1 4 7 10 13 16 19 22 25 28 30 5.11. As Partes reconhecem que, ao exercer responsabilidades de Contratação para a outra Parte ou ambas as Partes, em conformidade com um PA*, poderá ser necessário que a Parte Contratante incorra em obrigações contratuais ou outras em benefício da outra Parte ou de ambas as Partes, antes de receber os recursos da outra Parte. No caso em que a Parte Contratante incorra em tais obrigações contratuais ou outras obrigações, a outra Parte deverá pagar a sua parte equita | Da leitura do art. 5.12 depreende-se que, em caso de transferência de fundos de uma Parte a outra, somente a Parte beneficiária dos recursos deverá fazer auditoria, ao passo que, nas atividades de aquisição em geral, ambas as Partes farão as próprias auditorias.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q8 Item 3 (TPS 2020): 1 4 7 10 13 16 19 22 25 28 30 5.11. As Partes reconhecem que, ao exercer responsabilidades de Contratação para a outra Parte ou ambas as Partes, em conformidade com um PA*, poderá ser necessário que a Parte Contratante incorra em obrigações contratuais ou outras em benefício da outra Parte ou de ambas as Partes, antes de receber os recursos da outra Parte. No caso em que a Parte Contratante incorra em tais obrigações contratuais ou outras obrigações, a outra Parte deverá pagar a sua parte equita | Considerando ser o Acordo RDT\&E um tratado internacional, e em conformidade com o disposto no art. 6.1, a atividade de contratação será regida, em última instância, por regras de direito internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q8 Item 4 (TPS 2020): 1 4 7 10 13 16 19 22 25 28 30 5.11. As Partes reconhecem que, ao exercer responsabilidades de Contratação para a outra Parte ou ambas as Partes, em conformidade com um PA*, poderá ser necessário que a Parte Contratante incorra em obrigações contratuais ou outras em benefício da outra Parte ou de ambas as Partes, antes de receber os recursos da outra Parte. No caso em que a Parte Contratante incorra em tais obrigações contratuais ou outras obrigações, a outra Parte deverá pagar a sua parte equita | É correto interpretar o disposto no art. 8.8.4 no sentido de que somente a Parte detentora do título de Invenção do Projeto poderá apresentar a terceiros países os pedidos de Patente. Área Livre CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 5/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q9 Item 1 (TPS 2020): 1 4 7 10 13 16 18 A maior volta ao mundo que eu dei foi na Amazônia (...) Isso explica a copiosa e variada literatura que existe hoje sobre a Terra Verde. Alguns filhos da Amazônia (...), como donos legítimos do assunto, torceram o nariz, com mal dissimulado azedume, aos adventícios que estudaram e descreveram a sua planície. – Barlaventistas! Era como os denominavam, pejorativamente, no Pará (...) Nuno Vieira acrescentou: “Literatos, quantos a espiem pelas escotilhas de navios ligeiros, com a p | O texto sugere que a “copiosa e variada literatura” (linha 2) “sobre a Terra Verde” (linha 3) resulta da cooperação acadêmica entre os escritores locais, “donos legítimos do assunto” (linha 4), e os cientistas não amazônicos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q9 Item 2 (TPS 2020): 1 4 7 10 13 16 18 A maior volta ao mundo que eu dei foi na Amazônia (...) Isso explica a copiosa e variada literatura que existe hoje sobre a Terra Verde. Alguns filhos da Amazônia (...), como donos legítimos do assunto, torceram o nariz, com mal dissimulado azedume, aos adventícios que estudaram e descreveram a sua planície. – Barlaventistas! Era como os denominavam, pejorativamente, no Pará (...) Nuno Vieira acrescentou: “Literatos, quantos a espiem pelas escotilhas de navios ligeiros, com a p | A frase de Nuno Vieira (linhas de 9 a 13) contém crítica aos literatos que acreditam fazer ciência amazônica, quando, na verdade, têm contato superficial com a realidade da região.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q9 Item 3 (TPS 2020): 1 4 7 10 13 16 18 A maior volta ao mundo que eu dei foi na Amazônia (...) Isso explica a copiosa e variada literatura que existe hoje sobre a Terra Verde. Alguns filhos da Amazônia (...), como donos legítimos do assunto, torceram o nariz, com mal dissimulado azedume, aos adventícios que estudaram e descreveram a sua planície. – Barlaventistas! Era como os denominavam, pejorativamente, no Pará (...) Nuno Vieira acrescentou: “Literatos, quantos a espiem pelas escotilhas de navios ligeiros, com a p | Segundo o texto, a imaginação do homem amazônico é uma predisposição imposta pela geografia, que lhe comprime entre as “infinitas melancolias” (linha 17) do rio e da floresta. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q10 Item 1 (TPS 2020): 1 4 7 10 12 Canudos não se rendeu. Exemplo único em toda a historia, resistiu ate ao esgotamento completo. Expugnado palmo a palmo, na precisão integral do termo, caiu no dia 5, ao entardecer, quando caíram os seus últimos defensores, que todos morreram. Eram quatro apenas: um velho, dois homens feitos e uma crianca, na frente dos quais rugiam raivosamente cinco mil soldados. Forremo-nos à tarefa de descrever os seus últimos momentos (…) Esta página, imaginamo-la sempre profundamente emocionante | No trecho “resistiu até ao esgotamento completo” (linha 2), se a preposição “a” for omitida, reescrevendo-se até o esgotamento, não haveria alteração no sentido da frase.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q10 Item 2 (TPS 2020): 1 4 7 10 12 Canudos não se rendeu. Exemplo único em toda a historia, resistiu ate ao esgotamento completo. Expugnado palmo a palmo, na precisão integral do termo, caiu no dia 5, ao entardecer, quando caíram os seus últimos defensores, que todos morreram. Eram quatro apenas: um velho, dois homens feitos e uma crianca, na frente dos quais rugiam raivosamente cinco mil soldados. Forremo-nos à tarefa de descrever os seus últimos momentos (…) Esta página, imaginamo-la sempre profundamente emocionante | O termo “Expugnado” (linha 2) tem o mesmo sentido de expulso, indicando que os guerreiros de Canudos foram expulsos gradualmente do território que ocupavam.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q10 Item 3 (TPS 2020): 1 4 7 10 12 Canudos não se rendeu. Exemplo único em toda a historia, resistiu ate ao esgotamento completo. Expugnado palmo a palmo, na precisão integral do termo, caiu no dia 5, ao entardecer, quando caíram os seus últimos defensores, que todos morreram. Eram quatro apenas: um velho, dois homens feitos e uma crianca, na frente dos quais rugiam raivosamente cinco mil soldados. Forremo-nos à tarefa de descrever os seus últimos momentos (…) Esta página, imaginamo-la sempre profundamente emocionante | O termo “Forremo-nos” (linha 7) poderia ser substituído por dediquemo-nos, sem prejuízo de seu conteúdo semântico, visto que o autor passará a descrever os últimos momentos de Canudos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q11 Item 1 (TPS 2020): Falar da Teoria das Relações Internacionais (TRI) parte das seguintes escolhas: a primeira, que as relações internacionais são uma área de estudo científico autônoma; a segunda refere-se às teorias que são abordadas e como são definidas; por fim, a terceira reside na demanda de contextualizar essas reflexões [...] A teoria (ou teorias) são reflexos de sua época, não sendo a época que deve se ajustar à teoria. PECEQUILO, C. S. Teoria das Relações Internacionais: o mapa do caminho – estudo e práti | O Primeiro Debate contribuiu para a autonomia científica das Relações Internacionais e resultou na consolidação do liberalismo como a principal teoria dessa área do conhecimento até a Segunda Guerra Mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q11 Item 2 (TPS 2020): Falar da Teoria das Relações Internacionais (TRI) parte das seguintes escolhas: a primeira, que as relações internacionais são uma área de estudo científico autônoma; a segunda refere-se às teorias que são abordadas e como são definidas; por fim, a terceira reside na demanda de contextualizar essas reflexões [...] A teoria (ou teorias) são reflexos de sua época, não sendo a época que deve se ajustar à teoria. PECEQUILO, C. S. Teoria das Relações Internacionais: o mapa do caminho – estudo e práti | O Comitê Britânico de Teoria de Política Internacional surgiu no contexto do Segundo Debate, e uma de suas contribuições teóricas foi a utilização do pensamento político dos 3R’s para explicar as relações internacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q11 Item 3 (TPS 2020): Falar da Teoria das Relações Internacionais (TRI) parte das seguintes escolhas: a primeira, que as relações internacionais são uma área de estudo científico autônoma; a segunda refere-se às teorias que são abordadas e como são definidas; por fim, a terceira reside na demanda de contextualizar essas reflexões [...] A teoria (ou teorias) são reflexos de sua época, não sendo a época que deve se ajustar à teoria. PECEQUILO, C. S. Teoria das Relações Internacionais: o mapa do caminho – estudo e práti | A lógica da anarquia é uma das principais divergências entre teóricos neorrealistas e construtivistas. Para os primeiros, a anarquia é um fato objetivo da realidade, que dá origem a um sistema de autoajuda. Para os segundos, a anarquia é um fato intersubjetivo da realidade, que resulta em uma cultura kantiana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q11 Item 4 (TPS 2020): Falar da Teoria das Relações Internacionais (TRI) parte das seguintes escolhas: a primeira, que as relações internacionais são uma área de estudo científico autônoma; a segunda refere-se às teorias que são abordadas e como são definidas; por fim, a terceira reside na demanda de contextualizar essas reflexões [...] A teoria (ou teorias) são reflexos de sua época, não sendo a época que deve se ajustar à teoria. PECEQUILO, C. S. Teoria das Relações Internacionais: o mapa do caminho – estudo e práti | A interdependência complexa é um conceito-chave da teoria neoliberal das Relações Internacionais. Esse conceito é definido como uma situação de dependência mútua entre dois ou mais atores, a qual reduz as assimetrias entre eles, diminui as possibilidades de conflito e eleva as possibilidades de cooperação. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q12 Item 1 (TPS 2020): O Tratado da Antártica completou mais de 60 anos em 2019, com uma história de avanços e de impasses que resultou tanto no incremento da cooperação internacional quanto em reivindicações territoriais por parte de alguns países. Ao longo dessa história, o Brasil demonstrou interesse na região por meio da implementação de iniciativas e ações específicas, como, por exemplo, o Programa Antártico Brasileiro (PROANTAR). Acerca desse assunto, julgue (C ou E) os itens a seguir. | O Tratado da Antártica decorreu da Conferência de Washington, realizada em 1959, e o documento retomou princípios que haviam sido enunciados pela Declaração de Escudero, a exemplo da liberdade científica e do uso da região apenas para fins pacíficos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q12 Item 2 (TPS 2020): O Tratado da Antártica completou mais de 60 anos em 2019, com uma história de avanços e de impasses que resultou tanto no incremento da cooperação internacional quanto em reivindicações territoriais por parte de alguns países. Ao longo dessa história, o Brasil demonstrou interesse na região por meio da implementação de iniciativas e ações específicas, como, por exemplo, o Programa Antártico Brasileiro (PROANTAR). Acerca desse assunto, julgue (C ou E) os itens a seguir. | O Brasil é um dos 12 membros signatários originais que ratificaram o Tratado da Antártica em 1961, data em que o documento entrou em vigor, ainda que o governo brasileiro tenha estabelecido sua primeira estação na região, a Estação Antártica Comandante Ferraz, apenas nos anos de 1980.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q12 Item 3 (TPS 2020): O Tratado da Antártica completou mais de 60 anos em 2019, com uma história de avanços e de impasses que resultou tanto no incremento da cooperação internacional quanto em reivindicações territoriais por parte de alguns países. Ao longo dessa história, o Brasil demonstrou interesse na região por meio da implementação de iniciativas e ações específicas, como, por exemplo, o Programa Antártico Brasileiro (PROANTAR). Acerca desse assunto, julgue (C ou E) os itens a seguir. | Embora o Tratado da Antártica aplique-se à área ao sul de 60 graus da latitude sul e tenha previsto a desmilitarização da região, ele não proscreveu que países com pretensões territoriais, como o Reino Unido e a Austrália, exercessem a soberania relativa sobre os respectivos territórios antárticos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q12 Item 4 (TPS 2020): O Tratado da Antártica completou mais de 60 anos em 2019, com uma história de avanços e de impasses que resultou tanto no incremento da cooperação internacional quanto em reivindicações territoriais por parte de alguns países. Ao longo dessa história, o Brasil demonstrou interesse na região por meio da implementação de iniciativas e ações específicas, como, por exemplo, o Programa Antártico Brasileiro (PROANTAR). Acerca desse assunto, julgue (C ou E) os itens a seguir. | O Protocolo de Madrid, assinado em 1991, proibiu a exploração de recursos minerais em território antártico até o ano de 2048, quando o Tratado da Antártica poderá ser revisto pelas Partes Consultivas e quaisquer modificações e emendas deverão contar com a aprovação dos 12 membros signatários originais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q13 Item 1 (TPS 2020): A diplomacia brasileira confere tratamento multilateral para lidar com as chamadas novas ameaças, como o crime organizado e o terrorismo, entre outras. Com relação a esse assunto, julgue (C ou E) os itens a seguir. | O Brasil aderiu ao Grupo 3+1, criado pelos Estados Unidos da América após os ataques terroristas em Buenos Aires no ano de 1992. O propósito desse grupo foi combater os crimes transnacionais e suas conexões com o terrorismo, e vice-versa, na região da Tríplice Fronteira, por meio da cooperação regional e do compartilhamento de informações de inteligência e de segurança.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q13 Item 2 (TPS 2020): A diplomacia brasileira confere tratamento multilateral para lidar com as chamadas novas ameaças, como o crime organizado e o terrorismo, entre outras. Com relação a esse assunto, julgue (C ou E) os itens a seguir. | O Acordo de Cooperação Policial Aplicável aos Espaços Fronteiriços entre os Estados Partes do MERCOSUL permite que as forças policiais de qualquer país mercosulino prendam, nos espaços fronteiriços, os narcotraficantes listados em um banco de dados comum do bloco. Essa prisão pode ser efetuada, inclusive, fora do território nacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q13 Item 3 (TPS 2020): A diplomacia brasileira confere tratamento multilateral para lidar com as chamadas novas ameaças, como o crime organizado e o terrorismo, entre outras. Com relação a esse assunto, julgue (C ou E) os itens a seguir. | No âmbito dos BRICS, como consta na Declaração de Brasília da cúpula de 2019, o Brasil compromete-se a combater o uso ilícito das tecnologias da informação e da comunicação, bem como a estabelecer marcos legais para a cooperação entre os países do grupo e garantir a segurança da informação e da comunicação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q13 Item 4 (TPS 2020): A diplomacia brasileira confere tratamento multilateral para lidar com as chamadas novas ameaças, como o crime organizado e o terrorismo, entre outras. Com relação a esse assunto, julgue (C ou E) os itens a seguir. | Apesar da diversificação da agenda do MERCOSUL, com a inclusão de temas como a cooperação financeira, o tráfico ilegal de imigrantes, a segurança regional, entre outros, não há nenhum tratado, acordo ou protocolo específico do bloco quanto à corrupção. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 7/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q14 Item 1 (TPS 2020): O sistema interamericano e a Organização dos Estados Americanos (OEA) tiveram que se readequar à nova conjuntura internacional do pós-Guerra Fria, principalmente no sentido de incorporar novos temas que passaram a emergir no mundo, o que acarretou implicações para o Brasil. Com base nessas informações, julgue (C ou E) os itens a seguir. | Em 1991, os Estados-membros da OEA aprovaram unanimemente o Compromisso de Santiago com a Democracia e a Renovação do Sistema Interamericano, por meio do qual estabeleceram a cláusula democrática que foi reforçada pela Carta Democrática Interamericana em 2001.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q14 Item 2 (TPS 2020): O sistema interamericano e a Organização dos Estados Americanos (OEA) tiveram que se readequar à nova conjuntura internacional do pós-Guerra Fria, principalmente no sentido de incorporar novos temas que passaram a emergir no mundo, o que acarretou implicações para o Brasil. Com base nessas informações, julgue (C ou E) os itens a seguir. | O Brasil ratificou a Convenção Interamericana contra a Corrupção em 2002. De acordo com essa convenção, os atos de corrupção envolvem, direta ou indiretamente, funcionários públicos ou pessoas que exerçam funções públicas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q14 Item 3 (TPS 2020): O sistema interamericano e a Organização dos Estados Americanos (OEA) tiveram que se readequar à nova conjuntura internacional do pós-Guerra Fria, principalmente no sentido de incorporar novos temas que passaram a emergir no mundo, o que acarretou implicações para o Brasil. Com base nessas informações, julgue (C ou E) os itens a seguir. | Após o 11 de setembro de 2001, o governo brasileiro invocou o Tratado Interamericano de Assistência Recíproca (TIAR) e propôs a resolução Ameaça Terrorista nas Américas ao órgão de consulta do TIAR, declarando que os atentados terroristas nos Estados Unidos da América representavam um ataque contra os países americanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q14 Item 4 (TPS 2020): O sistema interamericano e a Organização dos Estados Americanos (OEA) tiveram que se readequar à nova conjuntura internacional do pós-Guerra Fria, principalmente no sentido de incorporar novos temas que passaram a emergir no mundo, o que acarretou implicações para o Brasil. Com base nessas informações, julgue (C ou E) os itens a seguir. | No Comunicado Conjunto da III Conferência Ministerial Hemisférica de Luta contra o Terrorismo, realizada na Colômbia em janeiro de 2020, os países participantes afirmaram que o Hezbollah e suas organizações afiliadas são uma ameaça à segurança coletiva nas Américas. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q15 Item 1 (TPS 2020): As missões de paz representam uma das principais linhas de atuação diplomática do Brasil no campo da paz e da segurança internacional. Acerca da participação brasileira nessas missões, julgue (C ou E) os itens a seguir. | Mesmo com o término da Missão das Nações Unidas de Estabilização no Haiti (MINUSTAH) em 2017, o Brasil continua contribuindo com as missões de paz que estão em andamento, principalmente no Oriente Médio e na África Subsaariana.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q15 Item 2 (TPS 2020): As missões de paz representam uma das principais linhas de atuação diplomática do Brasil no campo da paz e da segurança internacional. Acerca da participação brasileira nessas missões, julgue (C ou E) os itens a seguir. | Depois da Força Interina das Nações Unidas no Líbano (UNIFIL), a Missão das Nações Unidas na República Democrática do Congo (MONUSCO) e a Missão das Nações Unidas no Sudão do Sul (UNMISS) são as duas missões de paz que atualmente contam com maior participação de funcionários brasileiros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q15 Item 3 (TPS 2020): As missões de paz representam uma das principais linhas de atuação diplomática do Brasil no campo da paz e da segurança internacional. Acerca da participação brasileira nessas missões, julgue (C ou E) os itens a seguir. | O Brasil participa da Missão Multidimensional Integrada das Nações Unidas para a Estabilização da República Centro-Africana (MINUSCA), ainda que a Resolução no 2.149/2014 do Conselho de Segurança das Nações Unidas tenha estabelecido que a atuação deveria ocorrer sob a égide do Capítulo VII da Carta das Nações Unidas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q15 Item 4 (TPS 2020): As missões de paz representam uma das principais linhas de atuação diplomática do Brasil no campo da paz e da segurança internacional. Acerca da participação brasileira nessas missões, julgue (C ou E) os itens a seguir. | Não obstante o mandato da Missão Multidimensional Integrada das Nações Unidas para a Estabilização do Mali (MINUSMA) autorize a França a usar a força contra organizações terroristas, como a Al-Qaeda no Magrebe Islâmico, o Brasil atualmente participa dessa missão, e o governo brasileiro chegou a cogitar o envio do contingente militar que estava no Haiti para o Mali.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q16 Item 1 (TPS 2020): A partir dos anos de 1960, a África adquiriu maior relevância no âmbito da política externa brasileira, e o Brasil ampliou e diversificou as relações diplomáticas e comerciais com países africanos. A esse respeito, julgue (C ou E) os itens a seguir. | Não obstante a África do Sul participe de importantes arranjos diplomáticos com o Brasil, como o IBAS e o BRICS, em 2019, o principal país destino das exportações brasileiras no continente africano foi o Egito, e o principal país de origem das importações brasileiras da África foi a Argélia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q16 Item 2 (TPS 2020): A partir dos anos de 1960, a África adquiriu maior relevância no âmbito da política externa brasileira, e o Brasil ampliou e diversificou as relações diplomáticas e comerciais com países africanos. A esse respeito, julgue (C ou E) os itens a seguir. | Nos anos de 1970, Guiné-Bissau foi a primeira ex-colônia lusitana que teve a independência reconhecida pelo Brasil, o que marcou uma mudança de orientação da diplomacia brasileira em relação ao colonialismo português. O governo brasileiro, inclusive, chegou a reconhecer a independência do país antes mesmo de Portugal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q16 Item 3 (TPS 2020): A partir dos anos de 1960, a África adquiriu maior relevância no âmbito da política externa brasileira, e o Brasil ampliou e diversificou as relações diplomáticas e comerciais com países africanos. A esse respeito, julgue (C ou E) os itens a seguir. | O governo brasileiro propôs a criação da Zona de Paz e Cooperação do Atlântico Sul (ZOPACAS) em contraposição à proposta da Organização do Tratado do Atlântico Sul (OTAS), com o propósito de promover a cooperação regional e a paz e segurança entre países sul-americanos e africanos que compartilhavam o espaço do Atlântico Sul. Apesar de ter sido derrotada, a OTAS contou com o apoio de países que passaram a fazer parte da ZOPACAS.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q16 Item 4 (TPS 2020): A partir dos anos de 1960, a África adquiriu maior relevância no âmbito da política externa brasileira, e o Brasil ampliou e diversificou as relações diplomáticas e comerciais com países africanos. A esse respeito, julgue (C ou E) os itens a seguir. | Em 2013, Brasil e Nigéria estabeleceram o Mecanismo de Diálogo Estratégico durante a visita do chanceler brasileiro a Abuja. Dessa forma, a Nigéria tornou-se o único país da África Ocidental que detém um mecanismo dessa natureza com o governo brasileiro. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 8/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q17 Item 1 (TPS 2020): Comemoraram-se, em 2020, os 75 anos da Organização das Nações Unidas (ONU) e da adoção de sua Carta, assinada pelo Brasil em 26 de junho de 1945, em São Francisco, por ocasião da Conferência a respeito da Organização Internacional das Nações Unidas. Acerca da ONU, de sua Carta e da participação do Brasil na referida organização, julgue (C ou E) os itens a seguir. | O Brasil participou das negociações que levaram à criação da ONU e à adoção de sua Carta. Membros da delegação brasileira defenderam, com êxito, a inclusão, na Carta, dos princípios da não intervenção e da igualdade de direitos dos homens e das mulheres.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q17 Item 2 (TPS 2020): Comemoraram-se, em 2020, os 75 anos da Organização das Nações Unidas (ONU) e da adoção de sua Carta, assinada pelo Brasil em 26 de junho de 1945, em São Francisco, por ocasião da Conferência a respeito da Organização Internacional das Nações Unidas. Acerca da ONU, de sua Carta e da participação do Brasil na referida organização, julgue (C ou E) os itens a seguir. | A Corte Internacional de Justiça (CIJ), cujo estatuto é parte integrante da Carta da ONU, é o principal órgão judiciário da ONU e delibera a respeito de conflitos jurídicos entre Estados, além de preparar pareceres consultivos. Atualmente, a Corte conta um juiz brasileiro entre seus 15 membros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q17 Item 3 (TPS 2020): Comemoraram-se, em 2020, os 75 anos da Organização das Nações Unidas (ONU) e da adoção de sua Carta, assinada pelo Brasil em 26 de junho de 1945, em São Francisco, por ocasião da Conferência a respeito da Organização Internacional das Nações Unidas. Acerca da ONU, de sua Carta e da participação do Brasil na referida organização, julgue (C ou E) os itens a seguir. | O Brasil foi o primeiro país latino-americano a ocupar assento não permanente bienal no Conselho de Segurança (1946-1947). Hoje, integra o G-4 (juntamente com a Alemanha, a Índia e o Japão), que defende a expansão do Conselho de Segurança na categoria de membros permanentes, mantendo inalterado o número de membros não permanentes do órgão.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q17 Item 4 (TPS 2020): Comemoraram-se, em 2020, os 75 anos da Organização das Nações Unidas (ONU) e da adoção de sua Carta, assinada pelo Brasil em 26 de junho de 1945, em São Francisco, por ocasião da Conferência a respeito da Organização Internacional das Nações Unidas. Acerca da ONU, de sua Carta e da participação do Brasil na referida organização, julgue (C ou E) os itens a seguir. | A Assembleia Geral jamais logrou aprovar emendas aos artigos do capítulo V da Carta, referente ao Conselho de Segurança, o que confere legitimidade ao pleito do G4 pela reforma do principal órgão das Nações Unidas, responsável pela manutenção da paz e da segurança internacional. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q18 Item 1 (TPS 2020): O Brasil e outros atores regionais têm atuado conjuntamente em resposta às crises econômica, social, política, humanitária e de direitos humanos na Venezuela. No que se refere a essa temática, julgue (C ou E) os itens a seguir. | A suspensão da Venezuela do MERCOSUL, em agosto de 2017, foi uma das primeiras medidas tomadas no âmbito regional, com base no Protocolo de Ushuaia, o qual estabelece como condição essencial para o desenvolvimento do processo de integração do MERCOSUL a plena vigência das instituições democráticas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q18 Item 2 (TPS 2020): O Brasil e outros atores regionais têm atuado conjuntamente em resposta às crises econômica, social, política, humanitária e de direitos humanos na Venezuela. No que se refere a essa temática, julgue (C ou E) os itens a seguir. | Desde 2018, o Conselho de Direitos Humanos das Nações Unidas discute a situação dos direitos humanos na Venezuela. O Brasil, no entanto, não liderou a negociação de resoluções aprovadas relacionadas ao tema por defender, por princípio, que aquele órgão da Organização das Nações Unidas (ONU) não deveria tratar da situação dos direitos humanos em países específicos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q18 Item 3 (TPS 2020): O Brasil e outros atores regionais têm atuado conjuntamente em resposta às crises econômica, social, política, humanitária e de direitos humanos na Venezuela. No que se refere a essa temática, julgue (C ou E) os itens a seguir. | No âmbito regional, uma das mais importantes iniciativas de concertação diplomática para tratar da situação na Venezuela é a do Grupo de Lima, criado em 2017. O grupo apoia a restauração da democracia naquele país por meio de processo político pacífico e inclusivo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q18 Item 4 (TPS 2020): O Brasil e outros atores regionais têm atuado conjuntamente em resposta às crises econômica, social, política, humanitária e de direitos humanos na Venezuela. No que se refere a essa temática, julgue (C ou E) os itens a seguir. | A tentativa de acionamento do Tratado Interamericano de Assistência Recíproca (TIAR) para a situação da Venezuela foi infrutífera. A Reunião do Órgão de Consultas, previsto no tratado, realizada em Nova York em 2019, não logrou estabelecer a maioria necessária para aprovação de resolução com ações concretas referentes ao tema.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q19 Item 1 (TPS 2020): Em 2020, a Organização Mundial de Comércio (OMC) completou 25 anos de existência. Criada pelo Acordo de Marraqueche, a partir da bem-sucedida conclusão da Rodada Uruguai do antigo GATT (General Agreement on Tariffs and Trade), a OMC atua no monitoramento das práticas comerciais de seus Estados-membros, como foro permanente de negociações comerciais e como instância para a solução de controvérsias. Mais de duas décadas desde a sua criação, a OMC enfrenta críticas por não ter sido capaz de propici | O Brasil tem-se mostrado reticente a negociações que visem à reforma e à atualização das regras da OMC, com a introdução de novos temas, não cobertos pelo mandato negociador da Rodada Doha. Ademais, opõe-se ao lançamento de iniciativas plurilaterais no âmbito da OMC, por considerar que tais acordos enfraquecem o caráter multilateral da organização. Nos últimos anos, tem-se notabilizado, ainda, como defensor da retomada integral do mandato negociador da Rodada Doha, que ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q19 Item 2 (TPS 2020): Em 2020, a Organização Mundial de Comércio (OMC) completou 25 anos de existência. Criada pelo Acordo de Marraqueche, a partir da bem-sucedida conclusão da Rodada Uruguai do antigo GATT (General Agreement on Tariffs and Trade), a OMC atua no monitoramento das práticas comerciais de seus Estados-membros, como foro permanente de negociações comerciais e como instância para a solução de controvérsias. Mais de duas décadas desde a sua criação, a OMC enfrenta críticas por não ter sido capaz de propici | Em razão de o comércio exterior ter impacto relativamente pequeno para a economia brasileira, disputas comerciais no âmbito do Mecanismo de Solução de Controvérsias da OMC não constituem prioridade para a atuação do Brasil na organização. Sendo assim, o OSC em pouco contribuiu para a resolução de disputas comerciais de impacto financeiro relevante para o setor privado brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q19 Item 3 (TPS 2020): Em 2020, a Organização Mundial de Comércio (OMC) completou 25 anos de existência. Criada pelo Acordo de Marraqueche, a partir da bem-sucedida conclusão da Rodada Uruguai do antigo GATT (General Agreement on Tariffs and Trade), a OMC atua no monitoramento das práticas comerciais de seus Estados-membros, como foro permanente de negociações comerciais e como instância para a solução de controvérsias. Mais de duas décadas desde a sua criação, a OMC enfrenta críticas por não ter sido capaz de propici | O Brasil foi um dos principais patrocinadores da Declaração sobre o Acordo TRIPS e a Saúde Pública, adotada em 2001, que estabeleceu regras mais flexíveis para que países em desenvolvimento pudessem ter maior acesso a medicamentos. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q20 Item 1 (TPS 2020): Depois da entrada dos Estados Unidos da América (EUA) na Segunda Guerra (dezembro de 1941) e da aliança firmada na Declaração das Nações Unidas, a guerra foi paulatinamente pendendo em favor dos aliados e, entre eles, ficou mais clara a percepção da necessidade de se criar uma organização que preconizasse uma “trusteeship of the powerful”, ideia de Roosevelt pela qual caberia às potências vitoriosas a responsabilidade primária pela imposição da paz após a guerra, pela força se preciso. Na concep | Para o presidente norte-americano Franklin Delano Roosevelt, seria necessário formar um conselho com as principais potências mundiais e atribuir a tal conselho o sustento da segurança internacional. Na composição, quatro países fariam o papel de xerifes mundiais, responsáveis por manter a segurança regional: os EEUU nas Américas; a Grã-Bretanha na Europa; a URSS na Europa do Leste e nas regiões da Eurásia; a China na Ásia (podendo contar com a ajuda da URSS também no me', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q20 Item 2 (TPS 2020): Depois da entrada dos Estados Unidos da América (EUA) na Segunda Guerra (dezembro de 1941) e da aliança firmada na Declaração das Nações Unidas, a guerra foi paulatinamente pendendo em favor dos aliados e, entre eles, ficou mais clara a percepção da necessidade de se criar uma organização que preconizasse uma “trusteeship of the powerful”, ideia de Roosevelt pela qual caberia às potências vitoriosas a responsabilidade primária pela imposição da paz após a guerra, pela força se preciso. Na concep | O primeiro ministro britânico Winston Churchill, a seu turno, era a favor de criar tres conselhos: um para a Europa, um para a Ásia e outro para as Américas, a operarem sob a autoridade de um conselho supremo mundial, integrado pelos que fossem indiscutivelmente potências do ponto de vista militar. Na percepção do líder britânico, a Gra-Bretanha detinha, naquele momento, meios suficientes para arcar com o dever de policiar o mundo, mas poderia ceder, de alguma maneira, ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q20 Item 3 (TPS 2020): Depois da entrada dos Estados Unidos da América (EUA) na Segunda Guerra (dezembro de 1941) e da aliança firmada na Declaração das Nações Unidas, a guerra foi paulatinamente pendendo em favor dos aliados e, entre eles, ficou mais clara a percepção da necessidade de se criar uma organização que preconizasse uma “trusteeship of the powerful”, ideia de Roosevelt pela qual caberia às potências vitoriosas a responsabilidade primária pela imposição da paz após a guerra, pela força se preciso. Na concep | Roosevelt era simpático ao Brasil: visitou o País duas vezes (em 1936 e em 1943), tendo-se encontrado com Getúlio Vargas em ambas as ocasiões. Consta que o presidente norte-americano considerava o presidente brasileiro um parceiro confiável e o país amigo dos EUA, comprometido ademais com a segurança e a defesa do continente americano. Havia questões estratégicas prementes e, em face da guerra, o Brasil seria útil à alta política do Ocidente, em especial, quando se leva', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q21 Item 1 (TPS 2020): O MERCOSUL é uma prioridade da política externa brasileira. Desde a sua criação, o bloco contribuiu tanto para a integração entre os países sul-americanos quanto para o estreitamento das relações políticas e econômicas com países e blocos extrarregionais. Com base nessas informações, julgue (C ou E) os itens a seguir. | Em resposta aos protestos que aconteceram no Equador em outubro de 2019, os países do MERCOSUL emitiram uma nota conjunta para repudiar as situações de violência ocorridas em território equatoriano e para propor, em caráter provisório, a suspensão do país como membro associado do bloco.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q21 Item 2 (TPS 2020): O MERCOSUL é uma prioridade da política externa brasileira. Desde a sua criação, o bloco contribuiu tanto para a integração entre os países sul-americanos quanto para o estreitamento das relações políticas e econômicas com países e blocos extrarregionais. Com base nessas informações, julgue (C ou E) os itens a seguir. | Em 2019, o MERCOSUL e a Associação Europeia de Livre Comércio (EFTA) firmaram um acordo de livre comércio por meio do qual a segunda parte se comprometeu a eliminar todas as tarifas de importação dos setores industrial e pesqueiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q21 Item 3 (TPS 2020): O MERCOSUL é uma prioridade da política externa brasileira. Desde a sua criação, o bloco contribuiu tanto para a integração entre os países sul-americanos quanto para o estreitamento das relações políticas e econômicas com países e blocos extrarregionais. Com base nessas informações, julgue (C ou E) os itens a seguir. | Mais de um quinto das exportações brasileiras foi destinado ao MERCOSUL e à União Europeia em 2019. Se somados, os dois blocos representaram o segundo maior destino das exportações brasileiras no ano passado, atrás somente da China.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q21 Item 4 (TPS 2020): O MERCOSUL é uma prioridade da política externa brasileira. Desde a sua criação, o bloco contribuiu tanto para a integração entre os países sul-americanos quanto para o estreitamento das relações políticas e econômicas com países e blocos extrarregionais. Com base nessas informações, julgue (C ou E) os itens a seguir. | Os países do MERCOSUL e da Aliança do Pacífico assinaram o Acordo Quadro sobre Facilitação do Comércio no lançamento do Plano de Ação de Puerto Vallarta em 2018. No âmbito desse acordo, as partes comprometeram-se a reduzir em 15% as tarifas de importação do setor agrícola no prazo de cinco anos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q22 Item 1 (TPS 2020): A respeito da política externa brasileira nas décadas de 1950 e de 1960, julgue (C ou E) os itens a seguir. | O governo brasileiro restabeleceu relações diplomáticas com o Japão em 1952, e o país asiático tornou-se o terceiro maior destino das exportações do Brasil no final da década de 1970.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q22 Item 2 (TPS 2020): A respeito da política externa brasileira nas décadas de 1950 e de 1960, julgue (C ou E) os itens a seguir. | O presidente Juscelino Kubitschek lançou a Operação Pan-Americana (OPA) durante a visita do presidente norte-americano Dwight D. Eisenhower ao Brasil, em 1960. A OPA foi uma iniciativa do governo brasileiro para atrair, sobretudo, capitais privados dos Estados Unidos da América em prol do desenvolvimento econômico de países latino-americanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q22 Item 3 (TPS 2020): A respeito da política externa brasileira nas décadas de 1950 e de 1960, julgue (C ou E) os itens a seguir. | Após reatar as relações diplomáticas com a União Soviética, o governo brasileiro buscou a ampliação e a diversificação de parcerias comerciais com países do Leste Europeu, por meio da criação da Coleste, em 1962. Ainda nesse ano, o Brasil inaugurou as legações diplomáticas em Budapeste e Bucareste.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q22 Item 4 (TPS 2020): A respeito da política externa brasileira nas décadas de 1950 e de 1960, julgue (C ou E) os itens a seguir. | Brasil e Paraguai assinaram a Ata das Cataratas em 1966, com o propósito de atenuar as rivalidades territoriais no Salto das Sete Quedas e de aproveitar conjuntamente os recursos hidrelétricos do rio Paraná. Nessa ata, os dois países concordaram em realizar a partilha igualitária da energia elétrica que eventualmente seria produzida nos desníveis do rio Paraná até a foz do rio Iguaçu. Geografia Itens de 23 a 28', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q23 Item 1 (TPS 2020): Com relação aos domínios morfoclimáticos brasileiros, julgue (C ou E) os itens a seguir. | O domínio das terras baixas florestadas da Amazônia compreende as planícies inundáveis, com matas de terra firme, várzeas e igapós. Situa-se aí a maior extensão de florestas tropicais-úmidas contínuas do planeta, contendo milhões de espécies de organismos e uma grande diversidade biológica, quando comparada a outros domínios vegetacionais. Estima-se que, em média, em um hectare de floresta de terra firme preservada, convivam cerca de 200 a 300 espécies de árvores.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q23 Item 2 (TPS 2020): Com relação aos domínios morfoclimáticos brasileiros, julgue (C ou E) os itens a seguir. | O domínio da caatinga é um dos três espaços semiáridos da América do Sul, verdadeira exceção no contexto climático e hidrológico brasileiro, tendo em vista o predomínio de climas úmidos e subúmidos intertropicais, do Amazonas ao Rio Grande do Sul. O vazio de precipitações naquele domínio pode durar de seis a sete meses. O período de chuvas, por sua vez, ocorre concentrado em alguns meses do ano, com características de regularidade, o que garante a perenidade dos poucos rios que atravessam aquele domínio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q23 Item 3 (TPS 2020): Com relação aos domínios morfoclimáticos brasileiros, julgue (C ou E) os itens a seguir. | Os chapadões cobertos por cerrados brasileiros pertencem ao bioma savânico. Os cerrados arbóreos têm fisionomia marcada por árvores geralmente tortuosas e espaçadas, com troncos de cortiça espessa e aspecto xeromórfico das árvores e dos arbustos, em razão da escassez de água, característica daquele domínio morfoclimático durante a estação mais seca. Os cerrados brasileiros, em contraste com as savanas africanas, são, portanto, secos em virtude da baixa umidade média observada em boa parte do ano. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 11/15 4 O domínio dos planaltos de araucária compreende as terras de altitude média da porção meridional do Brasil, cobertas originariamente por formações florestais de diferentes densidades e extensões, com destaque p', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q24 Item 1 (TPS 2020): No que se refere à distribuição espacial das atividades econômicas em nível mundial, julgue (C ou E) os itens a seguir. | Diferentemente da produção de bens de consumo de massa (como eletroeletrônicos), a produção de bens derivados de tecnologias consideradas estratégicas pelos Estados Nacionais (setores de defesa e aeroespacial, por exemplo) é, ainda hoje, objeto de proteção e incentivos governamentais, sendo, portanto, concentrada geograficamente em alguns países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q24 Item 2 (TPS 2020): No que se refere à distribuição espacial das atividades econômicas em nível mundial, julgue (C ou E) os itens a seguir. | Alguns minerais como o lítio, o cobalto, o grafite e o vanádio, necessários para a produção de smartphones, semicondutores, painéis solares, turbinas eólicas, carros elétricos e satélites, têm sua extração concentrada em um pequeno número de áreas produtoras. No entanto, a restrita localização geográfica das jazidas minerais não impede que a extração e a comercialização daqueles minérios sejam crescentemente realizadas por empresas nas quais predominam capitais de terceiros países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q24 Item 3 (TPS 2020): No que se refere à distribuição espacial das atividades econômicas em nível mundial, julgue (C ou E) os itens a seguir. | A tendência observada de outsourcing, offshoring, associações, clusters, redes e terceirização em escala mundial nas cadeias de fornecimento mostrou-se imune a eventuais aumentos de custos econômicos e políticos decorrentes da expansão geográfica da produção industrial. Nesse sentido, não se observam, nos últimos anos, estímulos para o chamado reshoring em cadeias produtivas internacionalizadas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q24 Item 4 (TPS 2020): No que se refere à distribuição espacial das atividades econômicas em nível mundial, julgue (C ou E) os itens a seguir. | Nas últimas décadas, a queda nos custos de transporte e comunicação diminuiu a proteção historicamente conferida a significativo número de setores produtivos que se beneficiavam da proximidade dos mercados locais, eliminando, dessa forma, produtores pouco competitivos. Algumas atividades econômicas, como a indústria do vinho e o turismo, no entanto, souberam extrair rendas adicionais derivadas das características únicas (naturais, arquitetônicas, históricas) do território. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q25 Item 1 (TPS 2020): Em razão do volume de conhecimentos científicos e de procedimentos para alcançá-los, a necessidade de uma divisão do trabalho científico se impôs. As disciplinas específicas procuraram aperfeiçoar os princípios da ciência moderna e adaptá-los aos objetos de estudos particulares. LENCIONI, Sandra. Região e Geografia. São Paulo: EDUSP, 2003, p. 80, com adaptações. Com base no exposto, considerando as afirmações acerca dos principais conceitos utilizados pela Geografia ao longo da formação e consol | As diversas versões da chamada Geografia tradicional privilegiaram os conceitos de paisagem e região, estabelecendo, em torno desses conceitos, a discussão a respeito do objeto da Geografia e de sua identidade no âmbito das disciplinas científicas. Paisagem, região natural, região-paisagem, região geográfica, paisagem cultural e gênero de vida, por exemplo, foram conceitos amplamente utilizados pelos geógrafos vinculados ao positivismo e ao historicismo do século 19 e d', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q25 Item 2 (TPS 2020): Em razão do volume de conhecimentos científicos e de procedimentos para alcançá-los, a necessidade de uma divisão do trabalho científico se impôs. As disciplinas específicas procuraram aperfeiçoar os princípios da ciência moderna e adaptá-los aos objetos de estudos particulares. LENCIONI, Sandra. Região e Geografia. São Paulo: EDUSP, 2003, p. 80, com adaptações. Com base no exposto, considerando as afirmações acerca dos principais conceitos utilizados pela Geografia ao longo da formação e consol | A noção de região pode ser empregada na linguagem cotidiana como referência associada à localização e à extensão de determinado fato ou fenômeno e, da mesma forma, é comumente utilizada como unidade administrativa, sendo a base para a divisão regional adotada pela administração estatal. A noção de região geográfica, cientificamente mais rigorosa, nasce da ideia de que o ambiente natural tem certo domínio sobre a orientação do desenvolvimento da sociedade, condicionando ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q25 Item 3 (TPS 2020): Em razão do volume de conhecimentos científicos e de procedimentos para alcançá-los, a necessidade de uma divisão do trabalho científico se impôs. As disciplinas específicas procuraram aperfeiçoar os princípios da ciência moderna e adaptá-los aos objetos de estudos particulares. LENCIONI, Sandra. Região e Geografia. São Paulo: EDUSP, 2003, p. 80, com adaptações. Com base no exposto, considerando as afirmações acerca dos principais conceitos utilizados pela Geografia ao longo da formação e consol | A chamada revolução teorético-quantitativa da Geografia, iniciada na década de 1950, orientou-se pelo positivismo lógico, tendo como pressuposto a presença de uma ordem estrutural matemática implícita por trás do padrão empírico de organização espacial dos fenômenos. A tarefa da Geografia enquanto ciência seria a de descobrir e revelar esses padrões matemáticos no espaço, o qual passa a ser o conceito-chave da disciplina geográfica sob o paradigma teorético-quantitativo', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q25 Item 4 (TPS 2020): Em razão do volume de conhecimentos científicos e de procedimentos para alcançá-los, a necessidade de uma divisão do trabalho científico se impôs. As disciplinas específicas procuraram aperfeiçoar os princípios da ciência moderna e adaptá-los aos objetos de estudos particulares. LENCIONI, Sandra. Região e Geografia. São Paulo: EDUSP, 2003, p. 80, com adaptações. Com base no exposto, considerando as afirmações acerca dos principais conceitos utilizados pela Geografia ao longo da formação e consol | A Geografia da percepção e do comportamento, assim como a chamada Geografia humanista, procurou elaborar um enfoque globalizador e subjetivo da realidade, inserindo a intuição como elemento constitutivo do processo de conhecimento. Sua preocupação com o espaço vivido coloca, no centro da análise geográfica, o lugar. Não se trataria, no entanto, de um lugar em si, objetivo apenas, mas algo que transcende sua materialidade por ser repleto de significados. O lugar não seri', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q26 Item 1 (TPS 2020): A trajetória da agropecuária nacional, embora tenha seu desenvolvimento ligado a condições naturais favoráveis, é igualmente indissociável dos condicionantes históricos, políticos, sociais e geográficos que traçaram o processo de construção do espaço rural brasileiro. GUIMARÃES, Luiz Sérgio Pires. Evolução do espaço rural brasileiro. Rio de Janeiro: IBGE, 2016, com adaptações. Com base no fragmento do texto apresentado como referência inicial, acerca da estrutura fundiária, do uso da terra e das | O espaço rural brasileiro começou efetivamente a se estruturar no século 16, com a inserção da cana-de-açúcar na Região Nordeste. Por se destinar ao mercado interno, essa lavoura era desenvolvida da seguinte maneira: em larga escala; nos grandes latifúndios; com o uso extensivo do solo; com técnicas rudimentares; e com a utilização de mão de obra escrava.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q26 Item 2 (TPS 2020): A trajetória da agropecuária nacional, embora tenha seu desenvolvimento ligado a condições naturais favoráveis, é igualmente indissociável dos condicionantes históricos, políticos, sociais e geográficos que traçaram o processo de construção do espaço rural brasileiro. GUIMARÃES, Luiz Sérgio Pires. Evolução do espaço rural brasileiro. Rio de Janeiro: IBGE, 2016, com adaptações. Com base no fragmento do texto apresentado como referência inicial, acerca da estrutura fundiária, do uso da terra e das | Além da lavoura de cana-de-açúcar, cultivos que passaram a ser exportados no século 18, como algodão, cacau e tabaco, tiveram grande importância na estruturação do espaço rural brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q26 Item 3 (TPS 2020): A trajetória da agropecuária nacional, embora tenha seu desenvolvimento ligado a condições naturais favoráveis, é igualmente indissociável dos condicionantes históricos, políticos, sociais e geográficos que traçaram o processo de construção do espaço rural brasileiro. GUIMARÃES, Luiz Sérgio Pires. Evolução do espaço rural brasileiro. Rio de Janeiro: IBGE, 2016, com adaptações. Com base no fragmento do texto apresentado como referência inicial, acerca da estrutura fundiária, do uso da terra e das | A produção agropecuária no Brasil da década de 1940 estava estruturada sobre uma malha fundiária extremamente desigual. Ao lado de grandes estabelecimentos dedicados à pecuária e a lavouras de alto valor comercial, coexistiam pequenos estabelecimentos que praticavam uma agricultura destinada à subsistência.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q26 Item 4 (TPS 2020): A trajetória da agropecuária nacional, embora tenha seu desenvolvimento ligado a condições naturais favoráveis, é igualmente indissociável dos condicionantes históricos, políticos, sociais e geográficos que traçaram o processo de construção do espaço rural brasileiro. GUIMARÃES, Luiz Sérgio Pires. Evolução do espaço rural brasileiro. Rio de Janeiro: IBGE, 2016, com adaptações. Com base no fragmento do texto apresentado como referência inicial, acerca da estrutura fundiária, do uso da terra e das | No território brasileiro, a estrutura fundiária e a configuração do processo produtivo agropecuário consolidaram-se sob a gestão de diversas políticas públicas. Essas políticas tinham em comum a persistência de uma estrutura fundiária concentrada com predomínio da produção monocultora. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q27 Item 1 (TPS 2020): A respeito da estruturação e do funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os itens a seguir. | A agricultura científica globalizada, emergente na década de 1990, tem-se expressado como a nova forma de organização do agronegócio brasileiro. É caracterizada principalmente pela incorporação de novas tecnologias da informação ao campo e pela maior intervenção estatal. Trata-se da transição de um período de fraca intervenção estatal na agricultura, predominante desde a década de 1960, para uma maior regulação das empresas mundiais para o comércio agrícola (tradings).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q27 Item 2 (TPS 2020): A respeito da estruturação e do funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os itens a seguir. | Desde a década de 1940, a agricultura brasileira tem passado por um profundo reajustamento produtivo voltado a sua modernização. Esse processo tem sido permeado pelo crescente aumento das trocas intersetoriais e por um rearranjo técnico-econômico territorial resultante da contínua melhoria e ampliação dos sistemas logísticos de infraestrutura, de transporte e de armazenagem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q27 Item 3 (TPS 2020): A respeito da estruturação e do funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os itens a seguir. | O agronegócio engloba sistemas produtivos que vão desde a produção agropecuária até o seu beneficiamento, transformação e distribuição no mercado nacional e internacional e, em 2019, representou 21,4% do produto interno bruto (PIB) brasileiro. No Brasil e no mundo, esses sistemas produtivos prescindem de tecnologias voltadas ao aumento da produtividade da terra, do trabalho e do capital; exigem conhecimentos, tecnologias, investimentos e escala mínima de produção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q27 Item 4 (TPS 2020): A respeito da estruturação e do funcionamento do agronegócio no Brasil e no mundo, julgue (C ou E) os itens a seguir. | O Brasil dispõe da maior reserva de água doce do mundo, 12% do total, concentrada na região amazônica. É o único país continental do mundo cujo eixo principal está no sentido norte-sul. O País domina a mais avançada tecnologia de processo em agricultura tropical, resultante dos investimentos efetuados por instituições públicas e privadas de pesquisa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q28 Item 1 (TPS 2020): As cidades médias desempenham o papel de núcleo estratégico da rede urbana do Brasil, constituindo elos dos espaços urbano e regional, desempenhando, nos anos de 1970 e de 1980, função estratégica na política nacional de desenvolvimento urbano do País. A importância das cidades médias reside no fato de que elas possuem uma dinâmica econômica e demográfica própria, permitindo atender às expectativas de empreendedores e cidadãos, manifestados na qualidade de equipamentos urbanos e na prestação de  | A categoria de cidades médias no Brasil é oficialmente definida pelos critérios de localização, papel regional, densidade e porte demográfico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q28 Item 2 (TPS 2020): As cidades médias desempenham o papel de núcleo estratégico da rede urbana do Brasil, constituindo elos dos espaços urbano e regional, desempenhando, nos anos de 1970 e de 1980, função estratégica na política nacional de desenvolvimento urbano do País. A importância das cidades médias reside no fato de que elas possuem uma dinâmica econômica e demográfica própria, permitindo atender às expectativas de empreendedores e cidadãos, manifestados na qualidade de equipamentos urbanos e na prestação de  | Processos complexos e diversos, como a expansão do agronegócio, a desconcentração industrial e a expansão do setor de serviços, são responsáveis pela expansão das cidades médias pelo interior brasileiro. CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 13/15 3 O complexo agroindustrial de beneficiamento/ industrialização da produção agropecuária instala-se em cidades médias do interior brasileiro. Centros urbanos como Uberlândia (MG), Rio ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q28 Item 3 (TPS 2020): As cidades médias desempenham o papel de núcleo estratégico da rede urbana do Brasil, constituindo elos dos espaços urbano e regional, desempenhando, nos anos de 1970 e de 1980, função estratégica na política nacional de desenvolvimento urbano do País. A importância das cidades médias reside no fato de que elas possuem uma dinâmica econômica e demográfica própria, permitindo atender às expectativas de empreendedores e cidadãos, manifestados na qualidade de equipamentos urbanos e na prestação de  | As cidades médias são centralidades nos próprios contextos regionais, constituindo uma articulação da sua região de influência à economia mundial. Direito Itens de 29 a 34', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q29 Item 1 (TPS 2020): Com relação à responsabilidade civil do Estado, à improbidade administrativa, ao processo administrativo disciplinar e ao Regime Jurídico dos Servidores do Serviço Exterior Brasileiro (Lei no 11.440/2006), julgue (C ou E) os itens a seguir. | De acordo com a jurisprudência do Supremo Tribunal Federal (STF), conforme interpretação conferida ao art. 37, § 6o, da Constituição da República Federativa do Brasil (CRFB), a ação por danos causados por agente público deve ser proposta contra o Estado ou a pessoa jurídica de direito privado prestadora de serviço público, sendo parte ilegítima para a ação o autor do ato, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q29 Item 2 (TPS 2020): Com relação à responsabilidade civil do Estado, à improbidade administrativa, ao processo administrativo disciplinar e ao Regime Jurídico dos Servidores do Serviço Exterior Brasileiro (Lei no 11.440/2006), julgue (C ou E) os itens a seguir. | Consoante o atual entendimento do STF, são prescritíveis as ações de ressarcimento ao erário, fundadas na prática de ato doloso tipificado na Lei de Improbidade Administrativa (Lei no 8.429/1992).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q29 Item 3 (TPS 2020): Com relação à responsabilidade civil do Estado, à improbidade administrativa, ao processo administrativo disciplinar e ao Regime Jurídico dos Servidores do Serviço Exterior Brasileiro (Lei no 11.440/2006), julgue (C ou E) os itens a seguir. | Segundo o regime disciplinar estabelecido pela Lei no 8.112/1990, o processo disciplinar é o instrumento destinado a apurar responsabilidade de servidor por infração praticada no exercício de suas atribuições, ou que tenha relação com as atribuições do cargo em que se encontre investido.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q29 Item 4 (TPS 2020): Com relação à responsabilidade civil do Estado, à improbidade administrativa, ao processo administrativo disciplinar e ao Regime Jurídico dos Servidores do Serviço Exterior Brasileiro (Lei no 11.440/2006), julgue (C ou E) os itens a seguir. | Pela leitura das disposições da Lei no 11.440/2006, ao servidor do Serviço Exterior Brasileiro é permitido divulgar a cônjuge ou companheiro informação relevante para a política exterior do Brasil, a que tenha acesso em razão de desempenho de cargo no Serviço Exterior Brasileiro, ainda que sem anuência da autoridade competente. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q30 Item 1 (TPS 2020): No que concerne aos aspectos relacionados ao conceito de Constituição, ao controle de constitucionalidade, aos direitos fundamentais e às normas orçamentárias e de finanças públicas, julgue (C ou E) os itens a seguir. | De acordo com a jurisprudência do Supremo Tribunal Federal (STF), é formalmente constitucional resolução do Senado que autorize os estados, o Distrito Federal e os municípios a transferirem a cobrança das respectivas dívidas ativas a instituições financeiras.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q30 Item 2 (TPS 2020): No que concerne aos aspectos relacionados ao conceito de Constituição, ao controle de constitucionalidade, aos direitos fundamentais e às normas orçamentárias e de finanças públicas, julgue (C ou E) os itens a seguir. | Segundo o entendimento do STF, exige-se quórum de maioria absoluta dos membros do STF para modular os efeitos de decisão proferida em julgamento de recurso extraordinário no caso em que tenha ocorrido declaração de inconstitucionalidade de lei ou ato normativo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q30 Item 3 (TPS 2020): No que concerne aos aspectos relacionados ao conceito de Constituição, ao controle de constitucionalidade, aos direitos fundamentais e às normas orçamentárias e de finanças públicas, julgue (C ou E) os itens a seguir. | Conforme o entendimento do STF, o sigilo de informações necessário à preservação do direito fundamental à intimidade é relativizado quando há interesse da sociedade em conhecer o destino dos recursos públicos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q30 Item 4 (TPS 2020): No que concerne aos aspectos relacionados ao conceito de Constituição, ao controle de constitucionalidade, aos direitos fundamentais e às normas orçamentárias e de finanças públicas, julgue (C ou E) os itens a seguir. | A Constituição pode ser compreendida como um corpo de normas jurídicas (regras e princípios), qualificado pelo seu conteúdo e por sua função, as quais, estando ou não corporificadas em um documento (ou conjunto de documentos), assumem uma posição diferenciada e privilegiada em relação às demais normas jurídicas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q31 Item 1 (TPS 2020): Considerando aspectos da nacionalidade, da situação jurídica do estrangeiro, da apatridia e do asilo, julgue (C ou E) os itens a seguir. | O fato de o direito a ter uma nacionalidade estar consagrado na Declaração Universal dos Direitos Humanos de 1948 logrou praticamente a extinção do fenômeno da apatridia no século 21.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q31 Item 2 (TPS 2020): Considerando aspectos da nacionalidade, da situação jurídica do estrangeiro, da apatridia e do asilo, julgue (C ou E) os itens a seguir. | Nosso sistema jurídico-constitucional admite a aquisição de nacionalidade brasileira como efeito direto e imediato resultante do casamento civil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q31 Item 3 (TPS 2020): Considerando aspectos da nacionalidade, da situação jurídica do estrangeiro, da apatridia e do asilo, julgue (C ou E) os itens a seguir. | A concessão de asilo político é um dos princípios consagrados na Constituição Federal de 1988, constitui ato discricionário do Estado e é outorgado como instrumento de proteção à pessoa, mas não será concedido a quem tenha cometido crime contra a humanidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q31 Item 4 (TPS 2020): Considerando aspectos da nacionalidade, da situação jurídica do estrangeiro, da apatridia e do asilo, julgue (C ou E) os itens a seguir. | A Lei de Migração (Lei no 13.445/2017) assegura, como um de seus princípios e de suas diretrizes, o acesso igualitário e livre dos migrantes a serviços, programas e benefícios sociais, bens públicos, educação, assistência jurídica integral pública, trabalho, moradia, serviço bancário e seguridade social. Área Livre CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 14/15', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q32 Item 1 (TPS 2020): Acerca do Tribunal Penal Internacional e de sua importante relação com as Nações Unidas, em particular com o Conselho de Segurança, julgue (C ou E) os itens a seguir. | A atuação do Tribunal Penal Internacional baseia-se, como regra geral, na observância do princípio da complementaridade, que assegura a primazia das jurisdições penais nacionais no exercício da jurisdição.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q32 Item 2 (TPS 2020): Acerca do Tribunal Penal Internacional e de sua importante relação com as Nações Unidas, em particular com o Conselho de Segurança, julgue (C ou E) os itens a seguir. | A Conferência de Revisão do Estatuto de Roma, realizada em Campala em 2010, logrou definir o crime de agressão e estabelecer as condições para o exercício de jurisdição pelo Tribunal Penal Internacional. As emendas ao Estatuto dela resultantes foram assinadas e ratificadas pelo Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q32 Item 3 (TPS 2020): Acerca do Tribunal Penal Internacional e de sua importante relação com as Nações Unidas, em particular com o Conselho de Segurança, julgue (C ou E) os itens a seguir. | Pode o Conselho de Segurança, agindo nos termos do Capítulo VII da Carta das Nações Unidas, denunciar ao (à) procurador(a) do Tribunal Penal Internacional qualquer situação em que haja indícios de ter ocorrido a prática de crimes previstos no Estatuto de Roma.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q32 Item 4 (TPS 2020): Acerca do Tribunal Penal Internacional e de sua importante relação com as Nações Unidas, em particular com o Conselho de Segurança, julgue (C ou E) os itens a seguir. | O poder de o Conselho de Segurança solicitar adiamento do inquérito e do procedimento criminal no Tribunal Penal Internacional, por meio de resolução aprovada nos termos do disposto no Capítulo VII da Carta das Nações Unidas, está consignado no Estatuto de Roma e foi exercido na investigação da situação na Líbia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q33 Item 1 (TPS 2020): Em relação ao Direito dos Tratados e ao ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | A Convenção de Viena sobre o Direito dos Tratados, concluída em 23 de maio de 1969, somente foi promulgada sem reservas, no Brasil, em 14 de dezembro de 2009 pelo Decreto no 7.030.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q33 Item 2 (TPS 2020): Em relação ao Direito dos Tratados e ao ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | A regra que veda ao Estado invocar o fato de que seu consentimento em obrigar-se por um tratado foi expresso em violação de uma disposição de seu direito interno sobre competência para concluir tratados não admite exceção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q33 Item 3 (TPS 2020): Em relação ao Direito dos Tratados e ao ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | A formulação de reservas é, via de regra, facultada ao Estado que assina, ratifica, aceita, aprova ou adere a um tratado, mas o próprio tratado pode proibi-las. Exemplifica tal vedação o Estatuto de Roma, que criou o Tribunal Penal Internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q33 Item 4 (TPS 2020): Em relação ao Direito dos Tratados e ao ordenamento jurídico brasileiro, julgue (C ou E) os itens a seguir. | A Emenda Constitucional no 45/2004 estabelece que os tratados e as convenções internacionais a respeito de direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por maioria simples dos votos dos respectivos membros serão equivalentes às emendas constitucionais. Área Livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q34 Item 1 (TPS 2020): Considerando o atual quadro regulatório-institucional do Direito Internacional do Mar, bem como os direitos e as obrigações dos Estados, previstos na Convenção das Nações Unidas sobre o Direito do Mar (CNUDM), julgue (C ou E) os itens a seguir. | A CNUDM, ou Convenção de Montego Bay, assinada em 10 de dezembro de 1982, inaugura uma das concepções mais ambiciosas do diálogo e da cooperação internacionais sob os auspícios das Nações Unidas, tendo sido complementada, sobretudo, pelo Acordo Relativo à Implementação da Parte XI da CNUDM, concluído em Nova York, em 29 de julho de 1994, e pelo Acordo para a Implementação das Disposições da CNUDM sobre a Conservação e Ordenamento de Populações de Peixes Transzonais e de Populações de Peixes Altamente Migratórios, adotado em Nova York, em 4 de agosto de 1995.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q34 Item 2 (TPS 2020): Considerando o atual quadro regulatório-institucional do Direito Internacional do Mar, bem como os direitos e as obrigações dos Estados, previstos na Convenção das Nações Unidas sobre o Direito do Mar (CNUDM), julgue (C ou E) os itens a seguir. | Segundo a CNUDM, todo Estado tem o dever de fixar a largura do seu mar territorial em 12 milhas marítimas, medidas a partir de linhas de base determinadas em conformidade com a CNUDM.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q34 Item 3 (TPS 2020): Considerando o atual quadro regulatório-institucional do Direito Internacional do Mar, bem como os direitos e as obrigações dos Estados, previstos na Convenção das Nações Unidas sobre o Direito do Mar (CNUDM), julgue (C ou E) os itens a seguir. | A área e seus recursos, nela compreendidos ainda os recursos genéticos decorrentes da biodiversidade marinha para além dos limites de jurisdição nacional, são considerados patrimônio comum da humanidade em conformidade com o art. 136 da CNUDM.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2020, 'Economia', NULL, 'Q34 Item 4 (TPS 2020): Considerando o atual quadro regulatório-institucional do Direito Internacional do Mar, bem como os direitos e as obrigações dos Estados, previstos na Convenção das Nações Unidas sobre o Direito do Mar (CNUDM), julgue (C ou E) os itens a seguir. | Se reconhecida a jurisdição do Tribunal Internacional do Direito do Mar (TIDM) acerca de controvérsia relativa à interpretação ou aplicação da CNUDM, em virtude do art. 288 da CNUDM, o TIDM deve aplicar a CNUDM e outras normas de direito internacional que não forem incompatíveis com a CNUDM na resolução da controvérsia jurídico-internacional. Área Livre CONCURSO PÚBLICO TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA – TIPO “A” PÁGINA 15/15 Área Livre EDITAL No 1, DE 29 DE JUNHO DE 2020 CONCURSO DE ADMISSÃO À CARREIRA DE DIPLOMATA CARGO: TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA PRIMEIRA FASE – TARDE INSTRUÇÕES • Você receberá do fiscal: o 1 (um) caderno da prova objetiva contendo 39 (trinta e nove) questões, e cada ques', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
